/**
 * VaultIdentityStorage on @johnhenry/keyvault: compatibility with records
 * written by browsermesh-core 0.8.0 (fixtures/vault-pre-keyvault.json was
 * generated by that code, before the change), upgrade-on-unlock, and the
 * error behaviour the public API had before.
 */
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { needsUpgrade, open } from '@johnhenry/keyvault';
import {
  VaultIdentityStorage,
  InMemoryIdentityStorage,
  MeshIdentityManager,
} from '../src/identity.mjs';

const fx = JSON.parse(readFileSync(new URL('./fixtures/vault-pre-keyvault.json', import.meta.url), 'utf8'));

async function innerWith(record) {
  const inner = new InMemoryIdentityStorage();
  await inner.save('pod-1', record);
  return inner;
}
const vaultOf = (inner, pass) => new VaultIdentityStorage(inner, { getPassphrase: async () => pass });

describe('records written by browsermesh-core 0.8.0 still open', () => {
  for (const name of ['ascii-310k', 'unicode-nfd-310k', 'legacy-no-kdf']) {
    it(`opens ${name} and upgrades it on unlock`, async () => {
      const { passphrase, record } = fx.cases[name];
      assert.equal(typeof record.encryptedPrivateKey.ciphertext, 'string', 'fixture is the old shape');
      const inner = await innerWith(record);

      const loaded = await vaultOf(inner, passphrase).load('pod-1');
      assert.deepEqual(loaded.privateKeyJwk, fx.jwk);
      assert.equal(loaded.encryptedPrivateKey, undefined);
      assert.equal(loaded.label, name, 'metadata survives');

      // The record was rewritten with the current defaults.
      const after = await inner.load('pod-1');
      assert.equal(after.privateKeyJwk, null);
      assert.equal(after.label, name);
      assert.equal(after.encryptedPrivateKey.v, 1);
      assert.equal(after.encryptedPrivateKey.kdf.name, 'PBKDF2-SHA256');
      assert.ok(after.encryptedPrivateKey.kdf.iterations > 310_000, 'iterations raised');
      assert.equal(needsUpgrade(after.encryptedPrivateKey), false);
      assert.equal(JSON.stringify(after).includes('FIXTURE-PRIVATE-SCALAR'), false, 'no plaintext at rest');

      // And the rewritten record opens again, with the same passphrase.
      const again = await vaultOf(inner, passphrase).load('pod-1');
      assert.deepEqual(again.privateKeyJwk, fx.jwk);
    });
  }

  it('does not rewrite a record that is already current', async () => {
    const inner = new InMemoryIdentityStorage();
    await vaultOf(inner, 'pw').save('pod-1', { podId: 'pod-1', privateKeyJwk: fx.jwk });
    const before = JSON.stringify(await inner.load('pod-1'));
    let writes = 0;
    const save = inner.save.bind(inner);
    inner.save = (...a) => { writes++; return save(...a); };
    await vaultOf(inner, 'pw').load('pod-1');
    assert.equal(writes, 0);
    assert.equal(JSON.stringify(await inner.load('pod-1')), before);
  });

  it('does not normalise the passphrase when reading an old record', async () => {
    const { passphrase, record } = fx.cases['unicode-nfd-310k'];
    assert.notEqual(passphrase, passphrase.normalize('NFKC'), 'fixture passphrase is not NFKC');
    await assert.rejects(
      () => vaultOf(await_inner(record), passphrase.normalize('NFKC')).load('pod-1'),
      (e) => e.name === 'OperationError'
    );
  });

  it('a failed write-back does not fail the unlock', async () => {
    const { passphrase, record } = fx.cases['ascii-310k'];
    const inner = await innerWith(record);
    const save = inner.save.bind(inner);
    inner.save = async () => { throw new Error('quota exceeded'); };
    const loaded = await vaultOf(inner, passphrase).load('pod-1');
    assert.deepEqual(loaded.privateKeyJwk, fx.jwk);
    inner.save = save;
    assert.equal((await inner.load('pod-1')).encryptedPrivateKey.ciphertext !== undefined, true, 'old record untouched');
  });
});

function await_inner(record) {
  const inner = new InMemoryIdentityStorage();
  inner.save('pod-1', record);
  return inner;
}

describe('stored record shape (new writes)', () => {
  it('is a keyvault record, an object, with the rest of the record unchanged', async () => {
    const inner = new InMemoryIdentityStorage();
    await vaultOf(inner, 'pw').save('pod-1', { podId: 'pod-1', label: 'a', privateKeyJwk: fx.jwk });
    const rec = await inner.load('pod-1');
    assert.deepEqual(Object.keys(rec).sort(), ['encryptedPrivateKey', 'label', 'podId', 'privateKeyJwk']);
    assert.equal(rec.privateKeyJwk, null);
    const e = rec.encryptedPrivateKey;
    assert.equal(typeof e, 'object');
    assert.equal(e.t, 'browsermesh-vault');
    assert.equal(e.ciphertext, undefined, 'not the pre-keyvault envelope');
    const r = await open(e, 'pw', { type: 'browsermesh-vault' });
    assert.deepEqual(JSON.parse(new TextDecoder().decode(r.payload)), fx.jwk);
  });

  it('an older browsermesh-core fails clearly on a new record (does not misdecrypt)', async () => {
    // Re-implementation of the 0.8.0 guard: `kdf` was a string, and a record
    // whose kdf is anything else was refused before any key derivation.
    const inner = new InMemoryIdentityStorage();
    await vaultOf(inner, 'pw').save('pod-1', { podId: 'pod-1', privateKeyJwk: fx.jwk });
    const { encryptedPrivateKey: e } = await inner.load('pod-1');
    assert.notEqual(e.kdf, 'PBKDF2-SHA256');
    assert.equal(typeof e.kdf, 'object');
    assert.equal(e.ciphertext, undefined);
  });
});

describe('error behaviour is unchanged', () => {
  it('wrong passphrase rejects with a DOMException named OperationError', async () => {
    const inner = new InMemoryIdentityStorage();
    await vaultOf(inner, 'right').save('pod-1', { podId: 'pod-1', privateKeyJwk: fx.jwk });
    await assert.rejects(() => vaultOf(inner, 'wrong').load('pod-1'), (e) => {
      assert.equal(e.name, 'OperationError');
      assert.ok(e instanceof DOMException);
      return true;
    });
  });

  it('wrong passphrase on an old record is the same error, and the record is left alone', async () => {
    const { record } = fx.cases['ascii-310k'];
    const inner = await innerWith(record);
    await assert.rejects(() => vaultOf(inner, 'wrong').load('pod-1'), (e) => e.name === 'OperationError');
    assert.deepEqual(await inner.load('pod-1'), record);
  });

  it('unknown KDF keeps its message', async () => {
    const rec = structuredClone(fx.cases['ascii-310k'].record);
    rec.encryptedPrivateKey.kdf = 'ROT13';
    await assert.rejects(
      () => vaultOf(await_inner(rec), 'x').load('pod-1'),
      /Unsupported key derivation function: ROT13/
    );
  });

  it('still refuses empty and undefined passphrases', async () => {
    for (const v of ['', undefined, null, 5]) {
      await assert.rejects(
        () => vaultOf(new InMemoryIdentityStorage(), v).save('p', { privateKeyJwk: fx.jwk }),
        /getPassphrase must return a non-empty string passphrase/
      );
    }
  });
});

describe('encrypted identity export', () => {
  it('imports an export written by 0.8.0', async () => {
    const mgr = new MeshIdentityManager();
    const s = await mgr.import(fx.export.envelope, 'restored', { passphrase: fx.export.passphrase });
    const back = await mgr.export(s.podId);
    assert.equal(back.d, fx.export.jwk.d);
  });

  it('wrong passphrase on an old export gives the existing message', async () => {
    await assert.rejects(
      () => new MeshIdentityManager().import(fx.export.envelope, 'x', { passphrase: 'nope' }),
      /Could not read the encrypted identity export/
    );
  });

  it('new exports round-trip and are labelled encrypted', async () => {
    const a = new MeshIdentityManager();
    const s = await a.create('a');
    const env = await a.export(s.podId, 'pw pw');
    assert.equal(env.encrypted, true);
    assert.equal(JSON.stringify(env).includes('"d"'), false);
    const b = new MeshIdentityManager();
    const s2 = await b.import(env, 'b', { passphrase: 'pw pw' });
    assert.equal((await b.export(s2.podId)).d, (await a.export(s.podId)).d);
  });
});
